// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// ListAlerts Operator alerts, unresolved first
	// (GET /alerts)
	ListAlerts(ctx context.Context, request ListAlertsRequestObject) (ListAlertsResponseObject, error)
	// AckAlert Resolve an alert
	// (POST /alerts/{id}/ack)
	AckAlert(ctx context.Context, request AckAlertRequestObject) (AckAlertResponseObject, error)
	// ListAudit The admin audit log, newest first
	// (GET /audit)
	ListAudit(ctx context.Context, request ListAuditRequestObject) (ListAuditResponseObject, error)
	// AdminLogin Sign in with a username, a password and, once enrolled, a TOTP code
	// (POST /auth/login)
	AdminLogin(ctx context.Context, request AdminLoginRequestObject) (AdminLoginResponseObject, error)
	// AdminLogout End this admin session
	// (POST /auth/logout)
	AdminLogout(ctx context.Context, request AdminLogoutRequestObject) (AdminLogoutResponseObject, error)
	// AdminTotpFresh Prove the authenticator again, for the next five minutes
	// (POST /auth/totp/fresh)
	AdminTotpFresh(ctx context.Context, request AdminTotpFreshRequestObject) (AdminTotpFreshResponseObject, error)
	// ListInvites Invites, newest first
	// (GET /invites)
	ListInvites(ctx context.Context, request ListInvitesRequestObject) (ListInvitesResponseObject, error)
	// CreateInvite Make an invite link
	// (POST /invites)
	CreateInvite(ctx context.Context, request CreateInviteRequestObject) (CreateInviteResponseObject, error)
	// RevokeInvite Revoke an unused invite
	// (DELETE /invites/{id})
	RevokeInvite(ctx context.Context, request RevokeInviteRequestObject) (RevokeInviteResponseObject, error)
	// GetAdminMe The shell's bootstrap
	// (GET /me)
	GetAdminMe(ctx context.Context, request GetAdminMeRequestObject) (GetAdminMeResponseObject, error)
	// AckAdminNotices Dismiss the notices that predate this session
	// (POST /me/notices/ack)
	AckAdminNotices(ctx context.Context, request AckAdminNoticesRequestObject) (AckAdminNoticesResponseObject, error)
	// ChangeAdminPassword Replace the password
	// (POST /me/password)
	ChangeAdminPassword(ctx context.Context, request ChangeAdminPasswordRequestObject) (ChangeAdminPasswordResponseObject, error)
	// AdminTotpConfirm Prove the app has the secret and turn TOTP on
	// (POST /me/totp/confirm)
	AdminTotpConfirm(ctx context.Context, request AdminTotpConfirmRequestObject) (AdminTotpConfirmResponseObject, error)
	// AdminTotpSetup Make a TOTP secret, not yet enabled
	// (POST /me/totp/setup)
	AdminTotpSetup(ctx context.Context, request AdminTotpSetupRequestObject) (AdminTotpSetupResponseObject, error)
	// GetRegistration The registration mode
	// (GET /settings/registration)
	GetRegistration(ctx context.Context, request GetRegistrationRequestObject) (GetRegistrationResponseObject, error)
	// PutRegistration Change the registration mode
	// (PUT /settings/registration)
	PutRegistration(ctx context.Context, request PutRegistrationRequestObject) (PutRegistrationResponseObject, error)
	// GetRegistrationImpact What moving to a mode does to unproven claims
	// (GET /settings/registration/impact)
	GetRegistrationImpact(ctx context.Context, request GetRegistrationImpactRequestObject) (GetRegistrationImpactResponseObject, error)
	// GetWebauthn The Passkey configuration
	// (GET /settings/webauthn)
	GetWebauthn(ctx context.Context, request GetWebauthnRequestObject) (GetWebauthnResponseObject, error)
	// PutWebauthn Change the Passkey RP ID, or switch Passkey on or off
	// (PUT /settings/webauthn)
	PutWebauthn(ctx context.Context, request PutWebauthnRequestObject) (PutWebauthnResponseObject, error)
	// GetWebauthnImpact How many credentials a change of RP ID would make stale
	// (GET /settings/webauthn/impact)
	GetWebauthnImpact(ctx context.Context, request GetWebauthnImpactRequestObject) (GetWebauthnImpactResponseObject, error)
	// ListSmsGateways The gateways, never their credentials
	// (GET /sms/gateways)
	ListSmsGateways(ctx context.Context, request ListSmsGatewaysRequestObject) (ListSmsGatewaysResponseObject, error)
	// PutSmsGateway Set a gateway's credentials or price
	// (PUT /sms/gateways/{provider})
	PutSmsGateway(ctx context.Context, request PutSmsGatewayRequestObject) (PutSmsGatewayResponseObject, error)
	// PutSmsProviderTemplate Map a template to the provider's approved copy
	// (PUT /sms/gateways/{provider}/templates/{key}/{locale})
	PutSmsProviderTemplate(ctx context.Context, request PutSmsProviderTemplateRequestObject) (PutSmsProviderTemplateResponseObject, error)
	// TestSmsGateway Queue a test message through one gateway
	// (POST /sms/gateways/{provider}/test)
	TestSmsGateway(ctx context.Context, request TestSmsGatewayRequestObject) (TestSmsGatewayResponseObject, error)
	// GetSmsLimits The OTP caps and the SMS spending caps
	// (GET /sms/limits)
	GetSmsLimits(ctx context.Context, request GetSmsLimitsRequestObject) (GetSmsLimitsResponseObject, error)
	// PutSmsLimits Replace the limits
	// (PUT /sms/limits)
	PutSmsLimits(ctx context.Context, request PutSmsLimitsRequestObject) (PutSmsLimitsResponseObject, error)
	// GetSmsOutbox The state of one queued message
	// (GET /sms/outbox/{id})
	GetSmsOutbox(ctx context.Context, request GetSmsOutboxRequestObject) (GetSmsOutboxResponseObject, error)
	// PutSmsRouting Choose the primary and the fallback gateway
	// (PUT /sms/routing)
	PutSmsRouting(ctx context.Context, request PutSmsRoutingRequestObject) (PutSmsRoutingResponseObject, error)
	// GetSmsStats Messages and cost per day, attempts per gateway
	// (GET /sms/stats)
	GetSmsStats(ctx context.Context, request GetSmsStatsRequestObject) (GetSmsStatsResponseObject, error)
	// ListSmsTemplates The templates and their provider mappings
	// (GET /sms/templates)
	ListSmsTemplates(ctx context.Context, request ListSmsTemplatesRequestObject) (ListSmsTemplatesResponseObject, error)
	// PutSmsTemplate Change the text of a template
	// (PUT /sms/templates/{key}/{locale})
	PutSmsTemplate(ctx context.Context, request PutSmsTemplateRequestObject) (PutSmsTemplateResponseObject, error)
	// ReissueOneTimePassword Issue a user a new one-time password (T-536)
	// (POST /tenants/{tenant_id}/users/{user_id}/one-time-password)
	ReissueOneTimePassword(ctx context.Context, request ReissueOneTimePasswordRequestObject) (ReissueOneTimePasswordResponseObject, error)
	// ListUsers Users, newest first
	// (GET /users)
	ListUsers(ctx context.Context, request ListUsersRequestObject) (ListUsersResponseObject, error)
	// CreateUser Make a user with a one-time password
	// (POST /users)
	CreateUser(ctx context.Context, request CreateUserRequestObject) (CreateUserResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

